## Code Example
```javascript
import { beginPipeline, onFrame, pushFrame, stopPipeline } from 'NeuralRenderModule';

// Initialize the pipeline with target resolution and frame rate
await beginPipeline({
  resolution: { width: 1920, height: 1080 },
  targetFps: 60,
  style: 'neural-art',
});

// Register frame callback for processed output
onFrame((processedFrame) => {
  // Handle the stylized frame (e.g., display or stream)
  renderToSurface(processedFrame);
});

// Continuously feed frames from camera or video source
camera.on('frame', (frame) => {
  pushFrame(frame);
});

// Cleanup when done
stopPipeline();
```

